package middleware
import("context";"net/http";"strings";"go-repair-center/internal/platform/jwt";"go-repair-center/internal/transport/http/response")
func Auth(manager *jwt.Manager)func(http.Handler)http.Handler{return func(next http.Handler)http.Handler{return http.HandlerFunc(func(w http.ResponseWriter,r *http.Request){header:=r.Header.Get("Authorization");if !strings.HasPrefix(header,"Bearer "){response.Error(w,401,response.CodeUnauthorized,"missing access token",RequestID(r.Context()));return};claims,err:=manager.Parse(strings.TrimSpace(strings.TrimPrefix(header,"Bearer ")),"access");if err!=nil{response.Error(w,401,response.CodeUnauthorized,"invalid access token",RequestID(r.Context()));return};ctx:=context.WithValue(r.Context(),userIDKey,claims.UserID);ctx=context.WithValue(ctx,usernameKey,claims.Username);ctx=context.WithValue(ctx,permissionsKey,claims.Permissions);next.ServeHTTP(w,r.WithContext(ctx))})}}